package com.banksettings;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BankSettingsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankSettingsPlugin.class);
		RuneLite.main(args);
	}
}

package com.banksettings;

import java.util.function.Predicate;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarbitID;

/**
 * The three deposit buttons this plugin manages, with their component ids, server "hide" varbits
 * and decorative sprites across both the main bank and the deposit box.
 *
 * <p>Compliance note: the server-hide varbit is what lets the plugin honour the "never force-show a
 * button the game itself hid" rule. Where a varbit is {@link #NO_VARBIT} the game hides the button
 * conditionally (deposit-box inventory is always shown; the looting-bag button is shown only while
 * carrying a looting bag) and the natural state is snapshotted at build time instead.
 */
enum DepositButton
{
	INVENTORY(
		"Deposit inventory",
		"disableDepositInventory",
		SpriteID.Bankbuttons.DEPOSIT_INVENTORY, 1,
		InterfaceID.Bankmain.DEPOSITINV, VarbitID.BANK_HIDEDEPOSITINV,
		InterfaceID.Bankmain.DEPOSITINV_TOGGLE, InterfaceID.Bankmain.DEPOSITINV_GRAPHIC,
		InterfaceID.BankDepositbox.DEPOSIT_INV, -1,
		BankSettingsConfig::disableDepositInventory),

	WORN(
		"Deposit worn items",
		"disableDepositWorn",
		SpriteID.Bankbuttons.DEPOSIT_EQUIPMENT, 2,
		InterfaceID.Bankmain.DEPOSITWORN, VarbitID.BANK_HIDEDEPOSITWORN,
		InterfaceID.Bankmain.DEPOSITWORN_TOGGLE, InterfaceID.Bankmain.DEPOSITWORN_GRAPHIC,
		InterfaceID.BankDepositbox.DEPOSIT_WORN, VarbitID.DEPOSITBOX_HIDEDEPOSITWORN,
		BankSettingsConfig::disableDepositWorn),

	LOOT(
		"Deposit loot",
		"disableDepositLoot",
		SpriteID.Bankbuttons.DEPOSIT_LOOTING_BAG, 0,
		InterfaceID.Bankmain.DEPOSITCONTAINERS, VarbitID.BANK_HIDEDEPOSITCONTAINERS,
		InterfaceID.Bankmain.DEPOSITCONTAINERS_TOGGLE, InterfaceID.Bankmain.DEPOSITCONTAINERS_GRAPHIC,
		InterfaceID.BankDepositbox.DEPOSIT_LOOTINGBAG, -1,
		BankSettingsConfig::disableDepositLoot);

	/**
	 * Sentinel: the game has no user "hide" setting for this button in this interface. The enum
	 * constants above pass the literal {@code -1} (an enum constant may not forward-reference this
	 * field); everywhere else compares against this name.
	 */
	static final int NO_VARBIT = -1;

	final String label;
	final String configKey;
	final int spriteId;
	/** Canonical left-to-right slot the game lays the buttons out in: looting bag, inventory, worn. */
	final int naturalOrder;

	final int bankWidget;
	final int bankVarbit;
	final int bankToggle;
	/** The sprite child that renders the button's icon; a sibling of the button in the main bank. */
	final int bankGraphic;

	final int boxWidget;
	final int boxVarbit;

	private final Predicate<BankSettingsConfig> disabled;

	DepositButton(String label, String configKey, int spriteId, int naturalOrder,
		int bankWidget, int bankVarbit, int bankToggle, int bankGraphic,
		int boxWidget, int boxVarbit,
		Predicate<BankSettingsConfig> disabled)
	{
		this.label = label;
		this.configKey = configKey;
		this.spriteId = spriteId;
		this.naturalOrder = naturalOrder;
		this.bankWidget = bankWidget;
		this.bankVarbit = bankVarbit;
		this.bankToggle = bankToggle;
		this.bankGraphic = bankGraphic;
		this.boxWidget = boxWidget;
		this.boxVarbit = boxVarbit;
		this.disabled = disabled;
	}

	boolean disabledByConfig(BankSettingsConfig config)
	{
		return disabled.test(config);
	}
}

package com.banksettings;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BankSettingsConfig.GROUP)
public interface BankSettingsConfig extends Config
{
	String GROUP = "banksettings";

	@ConfigItem(
		keyName = "disableDepositInventory",
		name = "Disable Deposit inventory",
		description = "Client-side only: dims the Deposit inventory button in the bank and deposit box and stops it working. Changes no game settings.",
		position = 0
	)
	default boolean disableDepositInventory()
	{
		return false;
	}

	@ConfigItem(
		keyName = "disableDepositWorn",
		name = "Disable Deposit worn items",
		description = "Client-side only: dims the Deposit worn items button in the bank and deposit box and stops it working. Changes no game settings.",
		position = 1
	)
	default boolean disableDepositWorn()
	{
		return false;
	}

	@ConfigItem(
		keyName = "disableDepositLoot",
		name = "Disable Deposit loot",
		description = "Client-side only: dims the Deposit loot button in the bank and deposit box and stops it working. Changes no game settings.",
		position = 2
	)
	default boolean disableDepositLoot()
	{
		return false;
	}

	@ConfigItem(
		keyName = "moveDisabledLeft",
		name = "Move disabled buttons left",
		description = "Client-side only: shifts any disabled deposit buttons to the left of the strip so the active ones stay grouped. Repositions widgets only; changes no game settings.",
		position = 3
	)
	default boolean moveDisabledLeft()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSettingsIcons",
		name = "Show bank settings icons",
		description = "Client-side only: adds a small icon beside the inventory, equipment and looting-bag toggles on the bank settings page. Decorative only; changes no game settings.",
		position = 4
	)
	default boolean showSettingsIcons()
	{
		return true;
	}
}

package com.banksettings;

import com.google.inject.Provides;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontTypeFace;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Point;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Bank Settings: a client-side plugin that lets you disable the three deposit buttons in the bank
 * and deposit box. A disabled button stays visible but is dimmed and its click op is suppressed, so
 * it reads as greyed-out and does nothing. It changes no game settings, never sends a server/menu
 * action, and never force-shows a button the game itself hid.
 */
@Slf4j
@PluginDescriptor(
	name = "Bank Settings",
	description = "Disable deposit buttons in the bank and deposit box: dimmed and non-clickable. Changes no game settings.",
	tags = {"bank", "deposit", "settings", "disable", "buttons", "interface"}
)
public class BankSettingsPlugin extends Plugin
{
	// Feature 2 decorative-icon geometry. Icons are cosmetic only. Each icon sits at the left of its
	// settings-toggle row's text label, right of the state checkbox; we prepend spaces (LABEL_PREFIX)
	// to the label so its text shifts right and clears the icon. The icon is a no-op child of the row,
	// so it rides with the row and the row keeps its own Show/Hide click op. We re-check every client
	// tick because the settings page is built lazily and rebuilt on bank refresh. ICON_MARKER tags our
	// widgets so we never match the game's own sprites.
	private static final int ICON_SIZE = 20;
	private static final String ICON_MARKER = "banksettings_icon";

	// Each settings label is replaced with LABEL_PREFIX (spaces the icon sits over, at the label's left)
	// followed by LABEL_TEXT. The original names ("'Deposit inventory' button", etc.) are long enough to
	// wrap once shifted right, so the icon carries the meaning and only "button" remains. Tune the space
	// count if the icon overlaps the text; the font's space width is not known from source.
	private static final String LABEL_PREFIX = "          ";
	private static final String LABEL_TEXT = "button";

	// Small right margin between the restyled label text and the row's (clipped) right edge so the text
	// is not clipped flush against the column divider when we right-size the row.
	private static final int LABEL_PAD = 2;

	// Widget opacity for a disabled button: 0 is fully opaque, 255 fully transparent, so this is
	// roughly half translucent. Read as "greyed out" without vanishing.
	private static final int DISABLED_OPACITY = 128;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BankSettingsConfig config;

	// Natural (game-set) hidden state of deposit-box buttons that have no server "hide" varbit,
	// snapshotted at box build time so a config toggle can be undone without force-showing them.
	private final Map<Integer, Boolean> naturalBoxHidden = new HashMap<>();

	// Original menu-op strings of buttons we have disabled, keyed by packed widget id. Snapshotted
	// before we strip the op so enabling can restore it (a config toggle does not rebuild the bank).
	private final Map<Integer, String[]> savedActions = new HashMap<>();

	// Original label text and row width of each settings toggle we have restyled, keyed by the toggle's
	// packed id, so both can be restored when the icons are turned off or the plugin stops.
	private final Map<Integer, LabelSnapshot> savedLabels = new HashMap<>();

	@Override
	protected void startUp()
	{
		clientThread.invokeLater(() ->
		{
			applyBank();
			snapshotBox();
			applyBox();
			syncBankIcons();
			reorder(false, config.moveDisabledLeft());
			reorder(true, config.moveDisabledLeft());
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(this::restore);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		int scriptId = event.getScriptId();
		if (scriptId == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			applyBank();
			syncBankIcons();
			reorder(false, config.moveDisabledLeft());
		}
		else if (scriptId == ScriptID.BANK_DEPOSITBOX_INIT)
		{
			snapshotBox();
			applyBox();
			reorder(true, config.moveDisabledLeft());
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		// The settings page positions its rows after the bank build, and may scroll, so keep the icons
		// tracking their rows live. Cheap: no-ops when the bank/settings page is not on screen.
		syncBankIcons();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BankSettingsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			applyBank();
			applyBox();
			reorder(false, config.moveDisabledLeft());
			reorder(true, config.moveDisabledLeft());
		});
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANK_DEPOSITBOX)
		{
			naturalBoxHidden.clear();
			// The box widgets are destroyed; drop any op snapshots we held for them.
			savedActions.keySet().removeIf(id -> (id >>> 16) == InterfaceID.BANK_DEPOSITBOX);
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		// A disabled button's op is stripped, so it produces no normal menu entry. Detect the hover
		// by position and offer "Enable". This runs on menu open, so it is right-click only.
		if (addEnableEntryForDisabledButton())
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		// Widget right-click menus tag their entries with the widget's packed id in param1.
		int widgetId = -1;
		for (MenuEntry entry : entries)
		{
			int param1 = entry.getParam1();
			if (isControlWidget(param1))
			{
				widgetId = param1;
				break;
			}
		}

		if (widgetId == -1)
		{
			return;
		}

		boolean box = (widgetId >>> 16) == InterfaceID.BANK_DEPOSITBOX;

		if (widgetId == InterfaceID.Bankmain.MENU_BUTTON || widgetId == InterfaceID.BankDepositbox.MENU_BUTTON)
		{
			// Settings gear: expose the full control panel for all three buttons.
			for (DepositButton button : DepositButton.values())
			{
				addToggleEntry(button, box);
			}
		}
		else
		{
			DepositButton button = buttonForWidget(widgetId, box);
			if (button != null)
			{
				addToggleEntry(button, box);
			}
		}
	}

	private boolean isControlWidget(int widgetId)
	{
		if (widgetId == InterfaceID.Bankmain.MENU_BUTTON || widgetId == InterfaceID.BankDepositbox.MENU_BUTTON)
		{
			return true;
		}

		boolean box = (widgetId >>> 16) == InterfaceID.BANK_DEPOSITBOX;
		return buttonForWidget(widgetId, box) != null;
	}

	private DepositButton buttonForWidget(int widgetId, boolean box)
	{
		for (DepositButton button : DepositButton.values())
		{
			if (widgetId == (box ? button.boxWidget : button.bankWidget))
			{
				return button;
			}
		}
		return null;
	}

	/**
	 * If the cursor is over a disabled button, append a right-click "Enable" entry. Returns true when
	 * handled. Server-hidden buttons are fully hidden, so they are never offered an Enable that would
	 * force-show them.
	 */
	private boolean addEnableEntryForDisabledButton()
	{
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null)
		{
			return false;
		}

		for (DepositButton button : DepositButton.values())
		{
			if (!button.disabledByConfig(config))
			{
				continue;
			}

			if (!bankServerHidden(button) && hoveredOver(button.bankWidget, mouse))
			{
				addEnableEntry(button);
				return true;
			}

			if (!boxServerHidden(button) && hoveredOver(button.boxWidget, mouse))
			{
				addEnableEntry(button);
				return true;
			}
		}

		return false;
	}

	private boolean hoveredOver(int widgetId, Point mouse)
	{
		Widget widget = client.getWidget(widgetId);
		if (widget == null || widget.isHidden())
		{
			return false;
		}

		Rectangle bounds = widget.getBounds();
		return bounds != null && bounds.contains(mouse.getX(), mouse.getY());
	}

	private void addEnableEntry(DepositButton button)
	{
		client.getMenu().createMenuEntry(1)
			.setOption("Enable " + button.label)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> configManager.setConfiguration(BankSettingsConfig.GROUP, button.configKey, false));
	}

	private void addToggleEntry(DepositButton button, boolean box)
	{
		// Compliance: never offer to enable a button the game itself hid, because we would then have
		// to force-show it. Only buttons under our control get a menu entry.
		if (serverHidden(button, box))
		{
			return;
		}

		boolean disabled = button.disabledByConfig(config);
		String option = (disabled ? "Enable " : "Disable ") + button.label;

		// Index tunable in-client; appended so the button's default left-click op stays on top.
		client.getMenu().createMenuEntry(1)
			.setOption(option)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> configManager.setConfiguration(BankSettingsConfig.GROUP, button.configKey, !disabled));
	}

	private void applyBank()
	{
		for (DepositButton button : DepositButton.values())
		{
			boolean serverHidden = bankServerHidden(button);
			boolean disable = button.disabledByConfig(config) && !serverHidden;

			Widget widget = client.getWidget(button.bankWidget);
			if (widget != null)
			{
				if (serverHidden)
				{
					// The game hid the whole button; restore any op we stripped, then leave it hidden.
					enableWidget(widget, button.bankWidget);
					widget.setHidden(true);
				}
				else if (disable)
				{
					widget.setHidden(false);
					disableWidget(widget, button.bankWidget);
				}
				else
				{
					widget.setHidden(false);
					enableWidget(widget, button.bankWidget);
				}
			}

			// The button's icon is a separate sibling widget, so dim it to match the button.
			Widget graphic = client.getWidget(button.bankGraphic);
			if (graphic != null)
			{
				if (serverHidden)
				{
					graphic.setHidden(true);
				}
				else
				{
					setGraphicDimmed(graphic, disable);
				}
			}
		}
	}

	private void applyBox()
	{
		for (DepositButton button : DepositButton.values())
		{
			Widget widget = client.getWidget(button.boxWidget);
			if (widget == null)
			{
				continue;
			}

			boolean serverHidden = boxServerHidden(button);
			boolean disable = button.disabledByConfig(config) && !serverHidden;

			if (serverHidden)
			{
				enableWidget(widget, button.boxWidget);
				widget.setHidden(true);
			}
			else if (disable)
			{
				widget.setHidden(false);
				disableWidget(widget, button.boxWidget);
			}
			else
			{
				widget.setHidden(false);
				enableWidget(widget, button.boxWidget);
			}
		}
	}

	/**
	 * Dim a button and suppress its op so it reads as disabled and does nothing. Snapshots the op
	 * strings first (once) so {@link #enableWidget} can restore them.
	 */
	private void disableWidget(Widget widget, int widgetId)
	{
		if (!savedActions.containsKey(widgetId))
		{
			String[] actions = widget.getActions();
			savedActions.put(widgetId, actions == null ? null : actions.clone());
		}

		widget.setOpacity(DISABLED_OPACITY);
		widget.clearActions();
		widget.setHasListener(false);
		widget.setNoClickThrough(true);
		widget.revalidate();
	}

	/** Undo {@link #disableWidget}, restoring the button's op and full opacity. */
	private void enableWidget(Widget widget, int widgetId)
	{
		boolean wasDisabled = savedActions.containsKey(widgetId);
		if (!wasDisabled && widget.getOpacity() == 0)
		{
			// Already in its normal state; avoid a needless revalidate (and flicker) each rebuild.
			return;
		}

		if (wasDisabled)
		{
			String[] actions = savedActions.remove(widgetId);
			if (actions != null)
			{
				for (int i = 0; i < actions.length; i++)
				{
					if (actions[i] != null)
					{
						widget.setAction(i, actions[i]);
					}
				}
			}

			widget.setHasListener(true);
			widget.setNoClickThrough(false);
		}

		widget.setOpacity(0);
		widget.revalidate();
	}

	private void setGraphicDimmed(Widget graphic, boolean dim)
	{
		int target = dim ? DISABLED_OPACITY : 0;
		if (!graphic.isHidden() && graphic.getOpacity() == target)
		{
			return;
		}

		graphic.setHidden(false);
		graphic.setOpacity(target);
		graphic.revalidate();
	}

	/** Snapshot the deposit-box buttons that have no server varbit, before we apply our own hides. */
	private void snapshotBox()
	{
		for (DepositButton button : DepositButton.values())
		{
			if (button.boxVarbit != DepositButton.NO_VARBIT)
			{
				continue;
			}

			Widget widget = client.getWidget(button.boxWidget);
			if (widget != null)
			{
				naturalBoxHidden.put(button.boxWidget, widget.isHidden());
			}
		}
	}

	private boolean bankServerHidden(DepositButton button)
	{
		return client.getVarbitValue(button.bankVarbit) != 0;
	}

	private boolean boxServerHidden(DepositButton button)
	{
		if (button.boxVarbit != DepositButton.NO_VARBIT)
		{
			return client.getVarbitValue(button.boxVarbit) != 0;
		}

		Boolean natural = naturalBoxHidden.get(button.boxWidget);
		return natural != null && natural;
	}

	private boolean serverHidden(DepositButton button, boolean box)
	{
		return box ? boxServerHidden(button) : bankServerHidden(button);
	}

	// --- Feature 2: decorative icons in the main bank settings panel (cosmetic, no interactivity) ---

	/**
	 * Ensure each setting row has its decorative icon in the panel's left margin and keep it tracking
	 * the row's live position. Idempotent and self-healing: creates the icon if missing, repositions it
	 * when the row moves (layout/scroll), and hides it while the row is not visible. Cheap to call every
	 * client tick because it only revalidates when something actually changed.
	 */
	private void syncBankIcons()
	{
		boolean show = config.showSettingsIcons();

		for (DepositButton button : DepositButton.values())
		{
			Widget toggle = client.getWidget(button.bankToggle);
			if (toggle == null)
			{
				continue;
			}

			Widget label = findLabel(toggle);
			Widget icon = getIcon(toggle, button.spriteId);

			// Disabled, or the row/label is not on screen yet: hide our icon. When disabled, also put
			// the label text back. (Merely off screen: leave it blanked; the game rewrites the label on
			// its next rebuild, and we re-blank it then.)
			if (!show || label == null || effectivelyHidden(toggle) || toggle.getWidth() <= 0)
			{
				if (icon != null && !icon.isSelfHidden())
				{
					icon.setHidden(true);
					icon.revalidate();
				}
				if (!show && label != null)
				{
					restoreLabel(button.bankToggle, label);
				}
				continue;
			}

			// Snapshot the original label text and row width once so we can restore them later. Only
			// snapshot a row in its original (game) state, never our own restyled leftover, so a plugin
			// reload cannot capture our shrunk width/text as the "original".
			LabelSnapshot snap = savedLabels.get(button.bankToggle);
			if (snap == null)
			{
				String current = label.getText();
				if (current != null && current.startsWith(LABEL_PREFIX))
				{
					continue;
				}
				snap = new LabelSnapshot(current, toggle.getOriginalWidth());
				savedLabels.put(button.bankToggle, snap);
			}

			boolean rowChanged = false;

			// Replace the label with leading spaces (room for the icon) plus a short "button" so it does
			// not wrap. The Show/Hide op is on the row, not the label, so toggling still works.
			String target = LABEL_PREFIX + LABEL_TEXT;
			if (!target.equals(label.getText()))
			{
				label.setText(target);
				rowChanged = true;
			}

			// Right-size the row to the short content so a right-anchored row (the left column) pulls
			// tight to the column divider instead of leaving a gap where the long label used to be.
			// Left-anchored rows (right column) look the same either way; their trailing width was empty.
			FontTypeFace font = label.getFont();
			if (font != null)
			{
				int rowWidth = label.getRelativeX() + font.getTextWidth(target) + LABEL_PAD;
				if (toggle.getOriginalWidth() != rowWidth)
				{
					toggle.setOriginalWidth(rowWidth);
					rowChanged = true;
				}
			}

			if (rowChanged)
			{
				toggle.revalidate();
			}

			int x = label.getRelativeX();
			int y = label.getRelativeY() + (label.getHeight() - ICON_SIZE) / 2;

			if (icon == null)
			{
				icon = toggle.createChild(-1, WidgetType.GRAPHIC);
				icon.setName(ICON_MARKER);
				icon.setSpriteId(button.spriteId);
				icon.setOriginalWidth(ICON_SIZE);
				icon.setOriginalHeight(ICON_SIZE);
				icon.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
				icon.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			}

			boolean changed = false;
			if (icon.isSelfHidden())
			{
				icon.setHidden(false);
				changed = true;
			}
			if (icon.getOriginalX() != x || icon.getOriginalY() != y)
			{
				icon.setOriginalX(x);
				icon.setOriginalY(y);
				changed = true;
			}
			if (changed)
			{
				icon.revalidate();
			}
		}
	}

	/**
	 * Reorder the deposit buttons within their strip. When {@code disabledLeft} is set, disabled
	 * buttons are moved to the leftmost slots; otherwise the game's natural left-to-right order is
	 * restored. Both groups keep their canonical {@link DepositButton#naturalOrder}.
	 *
	 * <p>Compliance: only visible, non-server-hidden buttons are eligible, and we merely permute the
	 * X slots the game itself produced (read at runtime), so no button is force-shown or moved outside
	 * its strip. The buttons' icon sprite ({@code bankGraphic}) is a sibling in the bank, so it moves
	 * with its button; the deposit box buttons carry their sprite themselves and have no sibling.
	 */
	private void reorder(boolean box, boolean disabledLeft)
	{
		List<DepositButton> buttons = new ArrayList<>();
		List<Widget> widgets = new ArrayList<>();
		List<Widget> graphics = new ArrayList<>();

		for (DepositButton button : DepositButton.values())
		{
			if (serverHidden(button, box))
			{
				continue;
			}

			Widget widget = client.getWidget(box ? button.boxWidget : button.bankWidget);
			if (widget == null || widget.isHidden())
			{
				continue;
			}

			buttons.add(button);
			widgets.add(widget);
			graphics.add(box ? null : client.getWidget(button.bankGraphic));
		}

		int n = buttons.size();
		if (n < 2)
		{
			return;
		}

		// Home slots: the (buttonX, graphicX) pairs the game laid out, ordered left to right. Permuting
		// this fixed set keeps the assignment idempotent across rebuilds and repeated config toggles.
		Integer[] slot = new Integer[n];
		for (int i = 0; i < n; i++)
		{
			slot[i] = i;
		}
		Arrays.sort(slot, Comparator.comparingInt(i -> widgets.get(i).getOriginalX()));

		int[] slotButtonX = new int[n];
		int[] slotGraphicX = new int[n];
		for (int k = 0; k < n; k++)
		{
			Widget widget = widgets.get(slot[k]);
			Widget graphic = graphics.get(slot[k]);
			slotButtonX[k] = widget.getOriginalX();
			slotGraphicX[k] = graphic == null ? 0 : graphic.getOriginalX();
		}

		// Desired order: disabled buttons first (when enabled), each group by natural left-to-right order.
		Integer[] order = new Integer[n];
		for (int i = 0; i < n; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, Comparator
			.comparingInt((Integer i) -> disabledLeft && buttons.get(i).disabledByConfig(config) ? 0 : 1)
			.thenComparingInt(i -> buttons.get(i).naturalOrder));

		for (int k = 0; k < n; k++)
		{
			Widget widget = widgets.get(order[k]);
			if (widget.getOriginalX() != slotButtonX[k])
			{
				widget.setOriginalX(slotButtonX[k]);
				widget.revalidate();
			}

			Widget graphic = graphics.get(order[k]);
			if (graphic != null && graphic.getOriginalX() != slotGraphicX[k])
			{
				graphic.setOriginalX(slotGraphicX[k]);
				graphic.revalidate();
			}
		}
	}

	/** The settings-toggle row's text label (its sole TEXT child), or null if the row is not built yet. */
	private Widget findLabel(Widget toggle)
	{
		Widget[] children = toggle.getDynamicChildren();
		if (children == null)
		{
			return null;
		}

		for (Widget child : children)
		{
			if (child != null && child.getType() == WidgetType.TEXT)
			{
				return child;
			}
		}
		return null;
	}

	/** Put a restyled label's text and its row width back, and forget it. */
	private void restoreLabel(int toggleId, Widget label)
	{
		LabelSnapshot snap = savedLabels.remove(toggleId);
		if (snap == null)
		{
			return;
		}

		// Restore the row width first and revalidate the row, then the label, so a relative-width label
		// recomputes against the full-width row. Revalidating the label while the row is still narrow
		// squishes the restored long text.
		Widget toggle = client.getWidget(toggleId);
		if (toggle != null)
		{
			toggle.setOriginalWidth(snap.rowWidth);
			toggle.revalidate();
		}

		if (label != null)
		{
			label.setText(snap.text);
			label.revalidate();
		}
	}

	/** Find our icon for a button among the row's children, or null. Matches only our tagged widgets. */
	private Widget getIcon(Widget toggle, int spriteId)
	{
		Widget[] children = toggle.getDynamicChildren();
		if (children == null)
		{
			return null;
		}

		for (Widget child : children)
		{
			if (child != null && ICON_MARKER.equals(child.getName()) && child.getSpriteId() == spriteId)
			{
				return child;
			}
		}
		return null;
	}

	/** True if the widget or any ancestor is hidden (so the row is not actually on screen). */
	private boolean effectivelyHidden(Widget widget)
	{
		for (Widget w = widget; w != null; w = w.getParent())
		{
			if (w.isSelfHidden())
			{
				return true;
			}
		}
		return false;
	}

	/** Restore the game's own visibility, re-enable any disabled buttons and drop our icons on stop. */
	private void restore()
	{
		for (DepositButton button : DepositButton.values())
		{
			Widget bank = client.getWidget(button.bankWidget);
			if (bank != null)
			{
				enableWidget(bank, button.bankWidget);
				bank.setHidden(bankServerHidden(button));
			}

			Widget graphic = client.getWidget(button.bankGraphic);
			if (graphic != null)
			{
				graphic.setOpacity(0);
				graphic.setHidden(bankServerHidden(button));
				graphic.revalidate();
			}

			Widget box = client.getWidget(button.boxWidget);
			if (box != null)
			{
				enableWidget(box, button.boxWidget);
				box.setHidden(boxServerHidden(button));
			}

			Widget toggle = client.getWidget(button.bankToggle);
			if (toggle != null)
			{
				removeIcon(toggle, button.spriteId);
				restoreLabel(button.bankToggle, findLabel(toggle));
			}
		}

		// Put the buttons back in the game's natural left-to-right order.
		reorder(false, false);
		reorder(true, false);

		savedActions.clear();
		naturalBoxHidden.clear();
		savedLabels.clear();
	}

	private void removeIcon(Widget toggle, int spriteId)
	{
		Widget[] children = toggle.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		boolean removed = false;
		for (Widget child : children)
		{
			if (child != null && ICON_MARKER.equals(child.getName()) && child.getSpriteId() == spriteId)
			{
				child.setHidden(true);
				removed = true;
			}
		}

		if (removed)
		{
			toggle.revalidate();
		}
	}

	@Provides
	BankSettingsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankSettingsConfig.class);
	}

	/** The original label text and row width of a settings toggle, captured before we restyle it. */
	private static class LabelSnapshot
	{
		final String text;
		final int rowWidth;

		LabelSnapshot(String text, int rowWidth)
		{
			this.text = text;
			this.rowWidth = rowWidth;
		}
	}
}
